import time

MAX_ATTEMPTS = 4
REQUEST_TIMEOUT = 5.0
RETRY_BUDGET = 30.0
BACKOFF_BASE = 0.2


def with_backoff(call, attempts=MAX_ATTEMPTS, budget=RETRY_BUDGET, sleep=time.sleep):
    delay = BACKOFF_BASE
    for attempt in range(attempts):
        try:
            return call(timeout=REQUEST_TIMEOUT)
        except OSError:
            if attempt == attempts - 1:
                raise
            sleep(delay)
            delay *= 2

